// BAD (reject): L1 sequential, only L4 pipelined
L1: for (int i = 0; i < N; ++i) {              // trip=N, Pipelined=no
  L2: for (int j = 0; j < N; ++j) if (j<=i) C[i][j]*=beta;
  L3: for (int k = 0; k < M; ++k)
    L4: for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
      if (j<=i) C[i][j] += ...;
    }
}
// GOOD: see hls-syr2k-triangle-flatten-k-unroll

// BAD: parent pipelined, child loop remains
for (int i = 0; i < TILE; i++) {
#pragma HLS PIPELINE II=1
    for (int j = 0; j < N; j++) {  // child still exists
        A[i][j] = local_A[i][j];
    }
}
// GOOD: pipeline innermost only
for (int i = 0; i < TILE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        A[i][j] = local_A[i][j];
    }
}

// BAD (asks HLS to move whole row per cycle):
for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
    for (int j = 0; j < N; j++) A[i][j] = local_A[i][j];
    y[i] = local_y[i];
}
// GOOD:
for (int i = 0; i < TILE_SIZE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        A[i][j] = local_A[i][j];
    }
    y[i] = local_y[i];
}

// BAD: stacked outer-pipelined row loops in one task
void load_all(...) {
    for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) local_A[i][j] = A[...][j];
    }
    for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) local_B[i][j] = B[...][j];
    }
}
// GOOD: innermost pipeline per matrix or flat fused index
for (int i = 0; i < TILE_SIZE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        local_A[i][j] = A[tile_i + i][j];
    }
}

// BAD:
for (int k = 0; k < N; k++) {
#pragma HLS PIPELINE II=1
    w -= a[k] * b[k];
}
// GOOD: partial accumulators + final reduce (see hls-fp-reduction-partial-accumulators)

// BAD: one acc bank, k++
red_k: for (int k = 0; k < K; ++k) {
#pragma HLS PIPELINE II=1
  acc[i][j] += a_frag[i] * b_frag[j];  // Final II=4
}
// GOOD: k += 4, acc0..acc3 all written in this iteration.

// BAD: k++ plus switch — still II=4
for (int k = 0; k < K; ++k) {
#pragma HLS PIPELINE II=1
  switch (k & 3) { case 0: acc0[i][j] += ...; break; /* acc1/2/3 */ }
}
// GOOD: k += 4; write acc0, acc1, acc2, acc3 in this iteration.

// BAD: variable bound, tripcount pragma only
for (int k = 0; k < j; k++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
#pragma HLS PIPELINE II=1
    ...
}
// GOOD: fixed bound + guard
for (int k = 0; k < TILE_SIZE; k++) {
#pragma HLS PIPELINE II=1
    if (k < j) { ... }
}

// BAD: full k UNROLL with serial FP accumulator under (i,j) PIPELINE
for (int i = 0; i < M; ++i)
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    double sum = 0.0;
    for (int k = 0; k < K; ++k) {
#pragma HLS UNROLL
      sum += A[i][k] * B[k][j];  // carried dep → Final II ≫ 1 if 1×dadd
    }
    C[i][j] = sum;
  }
// GOOD: partial/tree reduction (or pipeline-on-k if resources cannot parallelize)

// BAD: RMW on local output inside pipelined unroll
for (int k = 0; k < UF; k++) {
#pragma HLS UNROLL
#pragma HLS PIPELINE II=1
    local_x[i] += A[i][j + k] * y[j + k];
}
// GOOD: partial accumulators, single write
partial[p] += A[i][j+p] * y[j+p];  // in pipelined loop
local_x[i] = reduce(partial);        // once after loop

